add(**C, name_ja="近代的自我", name_en="modern self (Japan)", name_original="近代的自我", period_key="明治期", definition="共同体的桎梏から離脱し独立した内面と意志を持つ主体の理念。北村透谷・夏目漱石『私の個人主義』に明示され、日本近代文学全体の基層的問題系を成す。", background="西欧近代の個人主義の翻訳的受容と日本的家族・国家との緊張。", development="漱石『こゝろ』『道草』、戦後実存主義文学まで持続する主題。", historical_context="明治国家の臣民像と近代的個人の対立。", primary_source_url=AOZORA+"cards/000148/card773.html", primary_source_type="青空文庫『こゝろ』", importance_score=5, source_tier="primary", canonical_in_region="core", cross_domain=[{"target_db":"PHIL","link_type":"shared_concept","target_entity_name":"主体性","description":"日本哲学（西田・和辻）と文学における近代的自我概念の交差。"}])
add(**C, name_ja="煩悶青年", name_en="anguished youth", name_original="煩悶青年", period_key="明治期", definition="日露戦争前後（1903年藤村操の華厳の滝投身を象徴とする）に出現した、人生の意味を問い苦悩する青年知識層の典型。漱石『三四郎』『それから』の主人公類型を生んだ。", background="近代教育の普及と立身出世主義の限界の顕在化。", development="戦後の太宰的自意識青年、戦後派の実存的青年に変奏される。", historical_context="高等教育の急拡大と社会的飽和。", primary_source_url=AOZORA+"cards/000148/card776.html", primary_source_type="青空文庫『三四郎』", importance_score=4, source_tier="primary", canonical_in_region="major")
add(**C, name_ja="自然と人間", name_en="nature and human", name_original="自然と人間", period_key="明治期", definition="自然描写を内面の客観的相関物として精緻化する近代日本文学の中心主題。国木田独歩『武蔵野』、徳冨蘆花『自然と人生』、川端『雪国』に至る系譜を成す。", background="ワーズワースなど英国ロマン派、ロシア文学の自然描写受容。", development="戦後の宮本輝・井上靖、現代の小川洋子の風景描写へ継承。", historical_context="近代化による自然の喪失意識の文学化。", primary_source_url=AOZORA+"cards/000038/card1672.html", primary_source_type="青空文庫『武蔵野』", importance_score=4, source_tier="primary", canonical_in_region="major")
add(**C, name_ja="家族解体", name_en="dissolution of the family", name_original="家族解体", period_key="現代", definition="近代家族の制度的崩壊と機能不全を主題化する戦後・現代文学の主題系。小島信夫『抱擁家族』（1965）が記念碑、現代では桐野夏生・川上未映子に至る。", background="戦後民法改正と高度成長期の核家族化、後の少子高齢化。", development="家族論論争（上野千鶴子等）と並走しつつ深化する。", historical_context="戦後核家族イデオロギーの破綻。", primary_source_url=NDL+"info:ndljp/pid/9540716", primary_source_type="NDL『抱擁家族』", importance_score=4, source_tier="secondary", canonical_in_region="major")
add(**C, name_ja="戦争体験", name_en="war experience", name_original="戦争体験", period_key="戦後期", definition="アジア・太平洋戦争の従軍・空襲・抑留・引揚体験を主題化する戦後文学の中核主題。大岡昇平『野火』『俘虜記』、野間宏『真空地帯』が代表する。", background="戦後の言論解放と作家自身の戦争被害・加害体験の語り直し要求。", development="原爆文学・在日文学・引揚者文学などサブジャンルへ展開。", historical_context="占領期の検閲緩和と戦後民主主義言論空間。", primary_source_url=AOZORA+"cards/001157/card59013.html", primary_source_type="青空文庫『俘虜記』関連", importance_score=5, source_tier="primary", canonical_in_region="core")
add(**C, name_ja="原爆文学", name_en="atomic bomb literature", name_original="原爆文学", period_key="戦後期", definition="広島・長崎の原爆体験を文学化したジャンル。原民喜『夏の花』、大田洋子『屍の街』、栗原貞子の詩、井伏鱒二『黒い雨』、林京子らに代表される。", background="占領下のプレスコード解除（1949以降）と被爆作家の証言活動。", development="国際的にもヒバクシャ文学として翻訳され、核時代の倫理文学の範例となる。", historical_context="冷戦下の核兵器論争と日本の特殊性。", primary_source_url=AOZORA+"cards/000293/card4204.html", primary_source_type="青空文庫『夏の花』", importance_score=5, source_tier="primary", canonical_in_region="core")
add(**C, name_ja="在日", name_en="Zainichi (Korean residents in Japan)", name_original="在日", period_key="戦後期", definition="植民地支配の帰結として日本に暮らす朝鮮系住民の体験を主題化する文学領域。金石範『火山島』、李恢成、金鶴泳、現代の柳美里・玄月らが日本語で書く。", background="植民地支配・解放後の南北分断・差別構造を背景とする。", development="日本語で書くことの政治性、母語と国籍の乖離が中心問題系を成す。", historical_context="戦後日本社会の単一民族神話とその限界。", primary_source_url=NDL+"info:ndljp/pid/12628000", primary_source_type="NDL 在日朝鮮人文学", importance_score=4, source_tier="secondary", canonical_in_region="major", fourth_axes=[{"axis":"主体","status":"rethinking","rationale":"国民国家・単一言語が前提する文学主体の同一性が、在日文学において根本的に揺らぐ。","related_ai_phenomenon":"多言語AI生成と国民文学概念の揺らぎ"},{"axis":"言語","status":"rethinking","rationale":"母語ではない日本語で書く実践が、AI翻訳時代の言語的真正性問題と接続する。","related_ai_phenomenon":"AIによる多言語横断執筆の倫理"}], cross_domain=[{"target_db":"AN","link_type":"shared_concept","target_entity_name":"周縁性／マイノリティ","description":"人類学のマイノリティ研究と在日文学の交差。"}])
add(**C, name_ja="周縁性", name_en="marginality", name_original="周縁性", period_key="現代", definition="国民国家・標準語・男性中心の文学的中心に対し、地方・女性・障害・マイノリティの位置から書く立場性。中上健次の路地、津島佑子の女性経験、目取真俊の沖縄が代表する。", background="ポストコロニアル批評・ジェンダー論の日本受容と近代文学批判。", development="現代日本文学の主流的問題系として制度化されつつある。", historical_context="戦後日本の均質化に対する反作用。", primary_source_url=NDL+"info:ndljp/pid/3137000", primary_source_type="NDL 中上健次関連", importance_score=4, source_tier="secondary", canonical_in_region="major", cross_domain=[{"target_db":"AN","link_type":"shared_concept","target_entity_name":"周縁性","description":"人類学的周縁性概念と文学的周縁性の交差。"}])
add(**C, name_ja="記憶/トラウマ", name_en="memory and trauma", name_original="記憶／トラウマ", period_key="現代", definition="個人的・歴史的トラウマと記憶の不可能な再構成を主題化する1990年代以降の文学。村上春樹『ねじまき鳥クロニクル』、多和田葉子、現代の朝井リョウ・上田岳弘までを貫く。", background="ホロコースト研究、トラウマ理論（カルース等）の翻訳受容、戦争責任議論の再活性化。", development="震災（阪神・東日本）後の記憶の文学として現在進行形で展開。", historical_context="戦後50年・60年の記憶論争と災害連続。", primary_source_url=NDL+"info:ndljp/pid/13001000", primary_source_type="NDL 記憶／トラウマ研究", importance_score=4, source_tier="secondary", canonical_in_region="major")
add(**C, name_ja="グローバル化と他者性", name_en="globalization and otherness", name_original="グローバル化と他者性", period_key="現代", definition="国境を越える移動・言語混淆・文化的他者性を主題化する現代日本文学の領域。多和田葉子の越境的作品、水村美苗『日本語が亡びるとき』、現代翻訳者作家まで広がる。", background="冷戦後のグローバル化と日本社会の国際化、海外日本研究の拡大。", development="日本語文学の国際的受容（村上春樹、川上弘美の英訳）と並走しつつ展開。", historical_context="ポスト冷戦の文化的越境状況。", primary_source_url=NDL+"info:ndljp/pid/9755000", primary_source_type="NDL 多和田葉子関連", importance_score=3, source_tier="secondary", canonical_in_region="major")
# --- 批評/理論 (10) ---
add(**C, name_ja="評論", name_en="hyōron (literary criticism)", name_original="評論", period_key="明治期", definition="作品論・作家論・思想論を含む日本近代独自の散文批評ジャンル。北村透谷、内田魯庵、明治末の島村抱月、戦後の小林秀雄に至り独自の文学的評論文が成立した。", background="西欧批評（マシュー・アーノルド等）と漢文評論の伝統の融合。", development="小林秀雄『様々なる意匠』『無常といふ事』が戦後に範型を確立した。", historical_context="新聞・雑誌メディアの拡大と知識人層の形成。", primary_source_url=AOZORA+"cards/000035/card2253.html", primary_source_type="青空文庫 小林秀雄", importance_score=4, source_tier="primary", canonical_in_region="core")
add(**C, name_ja="近代の超克論争", name_en="Overcoming Modernity debate", name_original="近代の超克", period_key="昭和戦前期", definition="1942年雑誌『文学界』座談会に端を発し、西欧近代の限界を東洋的伝統で乗り越えると論じた知識人の議論。京都学派（西谷啓治）、文学者（小林秀雄、中村光夫）が参加。", background="日中戦争・太平洋戦争の思想的正当化要求と、近代主義への戦前的疑念。", development="戦後、竹内好『近代の超克』再評価により、批判と継承が継続される論争史的事件。", historical_context="戦時動員と知識人の戦争協力。", primary_source_url=NDL+"info:ndljp/pid/1126000", primary_source_type="NDL『近代の超克』", importance_score=4, source_tier="secondary", canonical_in_region="core", cross_domain=[{"target_db":"PHIL","link_type":"shared_concept","target_entity_name":"近代批判","description":"哲学の近代批判（西田・京都学派）と文学的近代の超克論の交差。"}])
add(**C, name_ja="政治と文学", name_en="politics and literature debate", name_original="政治と文学", period_key="戦後期", definition="戦後すぐの中野重治・荒正人・平野謙らによる、文学の自律性と政治的責任の関係をめぐる論争。新日本文学会と『近代文学』派の対立軸として展開した。", background="戦時下の作家の戦争協力責任の追及と、戦後民主主義文学の方向性論争。", development="60年代の安保論争、70年代の三島事件と文学評論の関係まで余波が及ぶ。", historical_context="戦後思想の再編と転向問題の継続。", primary_source_url=JSTAGE+"article/jjla1971/", primary_source_type="J-STAGE 戦後文学論争", importance_score=4, source_tier="secondary", canonical_in_region="core")
add(**C, name_ja="私小説論争", name_en="shi-shōsetsu debate", name_original="私小説論争", period_key="戦後期", definition="中村光夫『風俗小説論』（1950）が私小説を「日本近代小説の歪み」と批判したことに始まる、戦後の長期的な私小説評価論争。伊藤整、平野謙、戦後派批評家を巻き込んだ。", background="戦後西欧近代小説（バルザック、トルストイ）の規範意識と日本的特殊性の対比。", development="現代でも私小説の再評価／批判は繰り返される批評史的論点。", historical_context="戦後文学批評の自己反省。", primary_source_url=NDL+"info:ndljp/pid/1666000", primary_source_type="NDL『風俗小説論』", importance_score=4, source_tier="secondary", canonical_in_region="core")
add(**C, name_ja="第三人称客観", name_en="third-person objective narration", name_original="第三人称客観描写", period_key="戦後期", definition="私小説的一人称主観に対し、客観的三人称で社会総体を描くべしとする戦後派の文学的要求。野間宏『真空地帯』、大岡昇平の試みに具体化された。", background="フローベール・トルストイ流のリアリズム小説への規範意識。", development="戦後派以降、社会派長篇小説の方法論的基盤となる。", historical_context="戦後の社会総体把握への文学的要求。", primary_source_url=JSTAGE+"article/jjla1971/", primary_source_type="J-STAGE 戦後派研究", importance_score=3, source_tier="secondary", canonical_in_region="minor")
add(**C, name_ja="テクスト論受容", name_en="reception of text theory", name_original="テクスト論", period_key="現代", definition="バルト・デリダ・クリステヴァらのテクスト論を1970-80年代に蓮實重彦・柄谷行人・浅田彰らが日本に導入し、作家論中心の批評からテクスト分析批評への転回を促した動向。", background="フランス現代思想の翻訳ブームと『現代思想』『批評空間』等の雑誌活動。", development="ポストモダン批評全般、現代の理論批評（東浩紀等）に継承。", historical_context="80年代の理論ブームと大学批評の隆盛。", primary_source_url=JSTAGE+"article/jjla1971/", primary_source_type="J-STAGE 現代批評理論研究", importance_score=4, source_tier="secondary", canonical_in_region="major")
add(**C, name_ja="カルチュラル・スタディーズ日本受容", name_en="Japanese reception of cultural studies", name_original="カルチュラル・スタディーズ受容", period_key="現代", definition="バーミンガム学派以降のカルチュラル・スタディーズを1990年代に上野俊哉・毛利嘉孝らが導入し、文学研究を大衆文化・サブカルチャー研究に拡張した動向。", background="サブカルチャー（マンガ・アニメ・J-POP）の学術対象化要求。", development="2000年代の「ポップカルチャー研究」、東浩紀のオタク論等に展開。", historical_context="文学研究の対象拡張と人文学の制度的再編。", primary_source_url=JSTAGE+"article/cs/", primary_source_type="J-STAGE 文化研究", importance_score=3, source_tier="secondary", canonical_in_region="minor")
add(**C, name_ja="ジェンダー批評日本受容", name_en="Japanese reception of gender criticism", name_original="ジェンダー批評", period_key="現代", definition="バトラー・スピヴァク等のジェンダー・ポストコロニアル理論を1990年代以降に上野千鶴子・水田宗子・小森陽一らが文学研究に応用した動向。日本近代文学の家父長性を批判的に再読した。", background="ウーマンリブ運動と女性学の制度化、第二波フェミニズム理論の翻訳。", development="現代の文学賞・カノン構成への批判的介入として継続。", historical_context="ポスト冷戦期の文化研究の多元化。", primary_source_url=JSTAGE+"article/joshigakuf/", primary_source_type="J-STAGE 女性学研究", importance_score=4, source_tier="secondary", canonical_in_region="major")
add(**C, name_ja="ポスト構造主義日本受容", name_en="Japanese reception of poststructuralism", name_original="ポスト構造主義受容", period_key="現代", definition="フーコー・デリダ・ドゥルーズらの思想を1980-90年代に蓮實重彦・浅田彰・柄谷行人・東浩紀らが文学批評に導入した動向。作者・主体・国民の解体的思考を促した。", background="フランス現代思想ブームとアカデミズムの理論武装。", development="現代の批評・理論研究（東浩紀『動物化するポストモダン』）に継承。", historical_context="80-90年代の高度資本主義文化の理論的把握要求。", primary_source_url=NDL+"info:ndljp/pid/12567000", primary_source_type="NDL ポスト構造主義関連", importance_score=4, source_tier="secondary", canonical_in_region="major")
add(**C, name_ja="デジタル批評", name_en="digital literary criticism", name_original="デジタル批評", period_key="現代", definition="デジタル人文学・テクストマイニング・電子書籍を対象とする2010年代以降の批評領域。文学研究の計量的転回（distant reading）と日本独自の批評ブログ・SNS批評を含む。", background="パソコン・インターネット普及と人文学の方法論的再編。", development="生成AI時代の批評（東浩紀、佐々木敦等）への接続が現在進行形。", historical_context="文学制度のデジタル変容。", primary_source_url=JSTAGE+"article/jadh/", primary_source_type="J-STAGE デジタル人文学", importance_score=3, source_tier="tertiary", canonical_in_region="minor")
