add(**C, name_ja="文壇", name_en="bundan (literary establishment)", name_original="文壇", period_key="明治期", definition="作家・批評家・編集者の閉じた共同体として成立した日本独特の文学制度。明治後期に形成され、新人発掘・評価・正典化を内部で完結させる構造を持った。", background="新聞・総合雑誌の発達と作家の専業化。", development="戦後も同人誌・出版社・文学賞を通じ持続したが、現代では弱体化。", historical_context="近代日本のメディア構造と作家の社会的位置。", primary_source_url=NDL+"info:ndljp/pid/2982000", primary_source_type="NDL 文壇史研究", importance_score=4, source_tier="secondary", canonical_in_region="core")
add(**C, name_ja="同人誌", name_en="dōjinshi (coterie magazine)", name_original="同人誌", period_key="明治期", definition="作家グループが自費で刊行する小規模文芸誌。『白樺』『文藝時代』『近代文学』など主要文学運動の母胎となった、日本近代文学の制度的特徴。", background="出版資本主義以前の文学的結社文化。", development="戦後同人誌、現代同人即売会（コミケ）まで実践形態が連続的に拡張。", historical_context="文学運動と読者形成の共同体的基盤。", primary_source_url=NDL+"info:ndljp/pid/2900000", primary_source_type="NDL 同人誌研究", importance_score=3, source_tier="secondary", canonical_in_region="major")
